def card(title,text,link):return f'<article {attrs("related-resources","resource-card")}><h3><a href="{link}">{title}</a></h3><p>{text}</p></article>'
nav=[('index.html','Home'),('departments.html','Departments'),('notices.html','Public notices'),('parking.html','Parking office'),('government.html','Government')]
pages={}
pages['index.html']=('Welcome to Alderhaven',f'''<div class="hero" {attrs('welcome','hero')}><div><p class="eyebrow">A city shaped together</p><h1>Welcome to Alderhaven</h1><p>Explore our fictional neighborhoods, discover city services, and find your place in the conversation.</p><a class="button" href="departments.html">Find a department</a></div><img src="assets/harbor.svg" alt="Original illustration of an imagined harbor city" width="720" height="420"></div>'''+sec('city-status','City status — sample day', '<p class="muted">Illustrative conditions for a fictional city. Never use this page for operational information.</p><div class="grid">'+card('Civic buildings','Sample status: open for a practice visit.','government.html#visit')+card('Street parking','Sample status: regular demonstration schedule.','parking.html#guidance')+card('Collection services','Sample status: sample routes on schedule.','departments.html#directory')+'</div>')+sec('popular','How can we help?', '<div class="grid">'+card('Understand a parking notice','Read the steps and try a clearly labeled practice inquiry.','parking.html#inquiry')+card('Explore public meetings','Browse fictional hearings and community discussions.','notices.html')+card('Learn how the city works','Explore the roles of a municipal government.','government.html')+'</div>')+sec('community','Around the city','<div class="feature"><p class="eyebrow">Community spotlight</p><h3>A new chapter for the river walk</h3><p>In this imagined planning story, neighbors are comparing ways to make the waterfront more welcoming. Read a sample discussion notice to learn how civic information is organized.</p><a href="notices.html">Explore sample notices →</a></div>'))
deps=[('Civic Records','Meeting records, public notices and research assistance.','notices.html','records'),('Community Spaces','Libraries, gathering places and neighborhood activities.','government.html#community','community'),('Mobility and Parking','Street use, parking guidance and sample inquiries.','parking.html','mobility'),('Neighborhood Services','A starting point for understanding city services.','government.html#help','community'),('Public Landscapes','Parks, street trees and imagined waterfront projects.','notices.html','landscapes'),('City Administration','How departments and civic leadership work together.','government.html','records')]
depcards=''.join(f'<article class="directory-row" data-search="{(n+" "+t).lower()}" {attrs("department-directory","directory-entry")}><h3><a href="{l}">{n}</a></h3><p>{t}</p></article>' for n,t,l,c in deps)
pages['departments.html']=('Departments','<h1>Departments</h1><p class="lead">Find the people and programs behind our fictional city.</p>'+sec('directory','Department directory',f'<label for="department-query">Search departments</label><input id="department-query" type="search" placeholder="Try parking or community"><p id="department-status" role="status">6 sample departments</p><div id="department-results" {attrs("department-directory","directory-list")}>{depcards}</div>'))
notices=[('River walk design conversation','Public Landscapes','November 18, 2030','Explore two imaginary paths for a shared waterfront.','landscapes'),('Neighborhood reading room discussion','Community Spaces','November 20, 2030','A sample agenda about flexible community space.','community'),('Street use policy workshop','Mobility and Parking','November 23, 2030','An illustrative discussion of curbside access.','mobility'),('Civic records advisory meeting','Civic Records','November 26, 2030','A practice notice about organizing public archives.','records')]
noticecards=''.join(f'<article class="notice" data-search="{(n+" "+t).lower()}" data-category="{c}" {attrs("notice-results","notice-card")}><p class="eyebrow">{t} · Fictional date: {d}</p><h3>{n}</h3><p>{x}</p><details {attrs("notice-results","notice-disclosure")}><summary>Read sample agenda</summary><p>1. Welcome and context. 2. Review the illustrative options. 3. Gather sample comments. This event does not exist; no attendance or registration is available.</p></details></article>' for n,t,d,x,c in notices)
