pages['parking.html']=('Parking office','<h1>Parking office</h1><p class="lead">Understand the process before you take the next step.</p><div class="split"><aside '+attrs('parking-navigation','section-nav')+'><h2>On this page</h2><a href="#guidance">Parking guidance</a><a href="#notices">Understand a notice</a><a href="#inquiry">Practice inquiry</a></aside><div>'+sec('guidance','Parking guidance','<p>The fictional Mobility and Parking office explains street-use policies and helps residents understand the kinds of records a parking office may maintain.</p><p>This demonstration does not supply parking rules, prices, deadlines or operational advice for any real place.</p>')+sec('notices','Understand a notice','<ol><li>Identify the issuing organization using its official channels.</li><li>Review the information and options in the actual notice.</li><li>Keep a record of your inquiry.</li></ol><p>No fines can be paid or disputed here.</p>')+sec('inquiry','Try a practice inquiry','<p>Research demo only. Use invented information. Nothing is transmitted or retained.</p><form id="inquiry-form" novalidate '+attrs('parking-inquiry','demo-form')+'><label for="sample-id">Sample notice ID (DEMO-101)</label><input id="sample-id" aria-describedby="inquiry-help" required><p id="inquiry-help">Enter DEMO-101 to explore a practice response.</p><label for="sample-topic">Your question</label><textarea id="sample-topic" rows="4" required></textarea><p id="inquiry-status" role="status" tabindex="-1"></p><button type="submit">Show demo response</button></form>')+'</div></div>')
pages['government.html']=('City government','<h1>City government</h1><p class="lead">Working together for a welcoming city.</p><div class="split"><aside '+attrs('government-navigation','section-nav')+'><h2>Explore this page</h2><a href="#leadership">Civic leadership</a><a href="#community">Community voice</a><a href="#visit">Civic spaces</a><a href="#help">Service help demo</a></aside><div>'+sec('leadership','Civic leadership','<p>In Alderhaven, an imagined council considers local policy and an administration coordinates everyday work. These descriptions illustrate municipal roles without naming real officials.</p><div class="grid">'+card('City administration','Explore the departments that carry out local programs.','departments.html')+card('Public discussion','See how meetings and their agendas may be announced.','notices.html')+'</div>')+sec('community','Community voice','<p>Ideas from neighborhoods help shape shared spaces. Our sample notices show the information someone might look for before joining a discussion.</p><a href="notices.html">Browse fictional discussions</a>')+sec('visit','Civic spaces','<p>The imaginary Civic Hall includes a reading room and public meeting space. No real address, opening hours or directions are provided.</p>')+sec('help','Service help demo','<p>The reference site hands off to a service contact route. This offline study uses a local demonstration instead.</p><button id="help-button" type="button" aria-expanded="false" aria-controls="help-panel">Explore service help</button><div id="help-panel" hidden '+attrs('service-help','demo-panel')+'><h3>Choose a sample topic</h3><p><a href="parking.html#inquiry">Parking inquiry practice</a> · <a href="departments.html">Find a sample department</a></p><p>This does not contact a government service. No real requests can be made.</p></div>')+'</div></div>')
