(root/'css/styles.css').write_text('''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#223b4d;background:#fff;font:18px/1.6 Arial,sans-serif}a{color:#075c80;text-underline-offset:4px}a:hover{text-decoration-thickness:3px}button,input,select,textarea{font:inherit}button,.button{background:#075c80;color:#fff;border:2px solid #075c80;padding:.6rem 1rem;cursor:pointer;border-radius:0}button:hover,.button:hover{background:#14394d;color:#fff}.button{display:inline-block;text-decoration:none}input,select,textarea{border:2px solid #627686;background:#fff;padding:.6rem;max-width:100%;color:#183549}input,textarea{width:100%}label{display:block;font-weight:bold;margin:.6rem 0 .3rem}button{min-height:44px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,[tabindex]:focus-visible{outline:4px solid #a94c00;outline-offset:4px}.skip{position:absolute;top:-100px;left:1rem;background:#fff;z-index:10;padding:1rem}.skip:focus{top:0}.demo-banner{background:#f4d897;color:#273849;padding:.5rem 4%;font-size:.85rem;font-weight:bold;text-align:center}header{padding:1.4rem 5% 0;border-bottom:5px solid #087ca0;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1rem}.brand{font-size:2rem;letter-spacing:2px;font-weight:900;color:#173d54;text-decoration:none}.brand span{display:block;letter-spacing:0;font-size:.75rem;text-transform:uppercase}.tools{display:flex;gap:.5rem}#primary-menu{display:flex;gap:2rem;width:100%;padding:1rem 0}#primary-menu a{text-decoration:none;font-weight:bold}a[aria-current]{text-decoration:underline!important;text-decoration-thickness:3px!important}#menu-button{display:none}.search-band{background:#edf3f4;padding:1rem 5%}.search-band form{max-width:800px}.search-band label{font-size:.9rem}.search-controls{display:flex;gap:.5rem}.search-band ul{margin:.7rem 0}.search-band li{margin:.3rem 0}main{max-width:1240px;margin:auto;padding:2rem 4% 4rem}h1{font-size:clamp(2.5rem,5vw,4.5rem);line-height:1.08;letter-spacing:-2px;margin:1.3rem 0}h2{font-size:2rem;line-height:1.2;margin-top:0}h3{font-size:1.35rem;line-height:1.35}.lead{font-size:1.5rem;max-width:800px}section{padding:2.5rem 0;border-top:1px solid #c6d3d7;margin-top:2rem}.hero{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:2rem;padding-bottom:2rem}.hero img{width:100%;height:auto}.eyebrow{text-transform:uppercase;letter-spacing:1px;font-size:.8rem;font-weight:bold}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.5rem}article{border-top:5px solid #087ca0;padding:1rem 1.2rem;background:#f0f5f5}.muted{color:#445e6c}.feature{padding:2rem;background:#edf3f4;border-left:8px solid #e3b45c}.split{display:grid;grid-template-columns:240px 1fr;gap:3rem}.split aside{padding:2rem 1rem;background:#edf3f4;align-self:start;margin-top:2rem}.split aside h2{font-size:1.2rem}.split aside a{display:block;margin-bottom:1rem}.directory-row{background:#fff;border-top:1px solid #c3cfd5;padding:1rem 0}.directory-row h3{margin:.4rem 0}.filters{display:flex;gap:1rem;flex-wrap:wrap;align-items:end}.filters>div{flex:1;min-width:180px}.notice{margin:1rem 0}details{border-top:1px solid #b0c6cf;padding:1rem 0}summary{cursor:pointer;font-weight:bold}#inquiry-status:not(:empty){padding:1rem;border-left:6px solid #a94c00;background:#fff1dc}#inquiry-form{max-width:650px}footer{background:#173d54;color:#fff;padding:3rem 5%}footer a{color:#fff}footer nav a{display:block}.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:3rem}footer h2{font-size:1.2rem}[hidden]{display:none!important}#language-panel,#help-panel{padding:1rem;background:#eef3f4;width:100%}@media(max-width:760px){.hero,.grid,.split,.footer-grid{grid-template-columns:1fr}#menu-button{display:block}#primary-menu{display:none;flex-direction:column;gap:1rem}#primary-menu.is-open{display:flex}.brand{font-size:1.5rem}.hero img{max-height:290px}.split{gap:0}.search-controls{align-items:stretch}.filters>button{flex:1}.tools{flex-wrap:wrap}h1{letter-spacing:-1px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}''')
(root/'js/main.js').write_text('''"use strict";
const demoPages=[{title:"Home and city status",url:"index.html",text:"city status community"},{title:"Departments",url:"departments.html",text:"directory records community landscapes"},{title:"Public notices",url:"notices.html",text:"meeting agenda notices discussion"},{title:"Parking office",url:"parking.html",text:"parking notice inquiry"},{title:"City government",url:"government.html",text:"government leadership service help"}];
function matches(text,query){return text.toLowerCase().includes(query.trim().toLowerCase());}
function filterRecords(records,query,category){return records.filter(r=>matches(r.dataset.search,query)&&(!category||r.dataset.category===category));}
function togglePanel(button,panel){const open=button.getAttribute("aria-expanded")!=="true";button.setAttribute("aria-expanded",String(open));panel.hidden=!open;return open;}
const menuButton=document.getElementById("menu-button"),menu=document.getElementById("primary-menu");
menuButton.addEventListener("click",()=>{const open=menuButton.getAttribute("aria-expanded")!=="true";menuButton.setAttribute("aria-expanded",String(open));menu.classList.toggle("is-open",open);});
for(const [buttonId,panelId] of [["language-button","language-panel"],["help-button","help-panel"]]){const button=document.getElementById(buttonId),panel=document.getElementById(panelId);if(button)button.addEventListener("click",()=>togglePanel(button,panel));}
document.addEventListener("keydown",event=>{if(event.key!=="Escape")return;for(const [buttonId,panelId] of [["language-button","language-panel"],["help-button","help-panel"]]){const b=document.getElementById(buttonId),p=document.getElementById(panelId);if(b&&b.getAttribute("aria-expanded")==="true"){b.setAttribute("aria-expanded","false");p.hidden=true;b.focus();return;}}if(menuButton.getAttribute("aria-expanded")==="true"){menuButton.setAttribute("aria-expanded","false");menu.classList.remove("is-open");menuButton.focus();}});
document.getElementById("site-search").addEventListener("submit",event=>{event.preventDefault();const query=document.getElementById("site-query").value;const results=demoPages.filter(p=>matches(p.title+" "+p.text,query));const box=document.getElementById("search-results");box.replaceChildren();const heading=document.createElement("p");heading.textContent=results.length+" local demo results";box.append(heading);const list=document.createElement("ul");list.dataset.section="global-search";list.dataset.component="search-result-list";for(const result of results){const item=document.createElement("li");item.dataset.section="global-search";item.dataset.component="search-result";const link=document.createElement("a");link.href=result.url;link.textContent=result.title;item.append(link);list.append(item);}box.append(list);if(!results.length)heading.textContent="No local demo results. Try parking, notices or departments.";});
const departmentQuery=document.getElementById("department-query");if(departmentQuery)departmentQuery.addEventListener("input",()=>{const records=Array.from(document.querySelectorAll(".directory-row"));const found=filterRecords(records,departmentQuery.value,"");records.forEach(r=>r.hidden=!found.includes(r));document.getElementById("department-status").textContent=found.length?found.length+" sample departments":"No departments match. Try parking or community.";});
const noticeForm=document.getElementById("notice-filter");function applyNotices(){const records=Array.from(document.querySelectorAll(".notice"));const found=filterRecords(records,document.getElementById("notice-query").value,document.getElementById("notice-category").value);records.forEach(r=>r.hidden=!found.includes(r));document.getElementById("notice-status").textContent=found.length?found.length+" sample notices":"No sample notices match. Clear the filters to start again.";}
if(noticeForm){noticeForm.addEventListener("submit",event=>{event.preventDefault();applyNotices();});noticeForm.addEventListener("reset",()=>{document.getElementById("notice-query").value="";document.getElementById("notice-category").value="";applyNotices();});}
const inquiry=document.getElementById("inquiry-form");if(inquiry)inquiry.addEventListener("submit",event=>{event.preventDefault();const id=document.getElementById("sample-id"),topic=document.getElementById("sample-topic"),status=document.getElementById("inquiry-status");id.removeAttribute("aria-invalid");topic.removeAttribute("aria-invalid");if(id.value.trim().toUpperCase()!=="DEMO-101"){status.textContent="Enter the sample notice ID DEMO-101. No real notice can be looked up here.";id.setAttribute("aria-invalid","true");id.focus();return;}if(topic.value.trim().length<10){status.textContent="Write a practice question of at least 10 characters using invented information.";topic.setAttribute("aria-invalid","true");topic.focus();return;}status.textContent="Demo complete: your practice question is ready for review. Nothing was sent, saved or submitted; this is not a real case or response.";status.focus();});
''')
